struct Node { int value; std::atomic<Node*> next; };
std::atomic<Node*> top{nullptr};

Node* pop() {
  Node* t = top.load();
  while (t != nullptr) {
    Node* n = t->next.load();          // read the successor
    if (top.compare_exchange_weak(t, n))
      return t;                        // we removed t
    // on failure, t now holds the current top; retry
  }
  return nullptr;
}

struct Node { int value; std::atomic<Node*> next; };
struct TaggedPtr { Node* ptr; std::uint64_t tag; };   // 16 bytes
std::atomic<TaggedPtr> top{TaggedPtr{nullptr, 0}};

Node* pop() {
  TaggedPtr old = top.load();                 // pointer and tag together
  while (old.ptr != nullptr) {
    TaggedPtr desired{old.ptr->next.load(), old.tag + 1};
    if (top.compare_exchange_weak(old, desired))
      return old.ptr;
    // failure reloaded old (both fields); retry
  }
  return nullptr;
}

bool pop(int& out) {
  Node* t;
  for (;;) {
    t = top.load();
    if (t == nullptr) return false;
    my_hazard.store(t);            // announce: I may use t
    if (top.load() != t) continue; // re-check t was still reachable
    Node* n = t->next.load();      // safe: t cannot be freed now
    if (top.compare_exchange_weak(t, n)) break;
  }
  out = t->value;                  // read t before retiring it
  my_hazard.store(nullptr);
  retire(t);                       // freed later, only if no slot holds t
  return true;
}
